(()=>{'use strict';
const STORE='sales_forecast_v16',RAW='https://raw.githubusercontent.com/yhbae106/Sales_Forecast/main/shared-data/sales-history.json';
const $=s=>document.querySelector(s),status=m=>{const e=$('#status');if(e)e.textContent=m};
const setBrand=()=>{const e=$('.eyebrow'),h=$('.top h1');if(e)e.textContent='SCM SALES Forecast CONTROL TOWER';if(h)h.textContent='종합도매 매출 · MBO 운영 대시보드';document.title='SCM SALES Forecast CONTROL TOWER | 종합도매 매출 · MBO 운영 대시보드'};
const short=d=>d?`${Number(d.slice(5,7))}/${Number(d.slice(8))}까지 반영 완료`:'공용 데이터 대기';
const load=src=>new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=src;s.async=false;s.onload=resolve;s.onerror=()=>reject(new Error(src+' 로드 실패'));document.body.appendChild(s)});
async function hydrate(){const r=await fetch(RAW+'?v=36&t='+Date.now(),{cache:'no-store'});if(!r.ok)throw new Error('공용 데이터 HTTP '+r.status);const shared=await r.json();const up=Array.isArray(shared.uploads)?shared.uploads:[];window.__SF_SHARED_UPLOADS=up;window.__sfSharedMeta=shared;let local={};try{local=JSON.parse(localStorage.getItem(STORE)||localStorage.getItem('sales_forecast_v15')||'{}')}catch(e){}const lean={mbo:local.mbo||{},gmbo:local.gmbo||local.groupMbo||{},sched:local.sched||{},up};try{localStorage.setItem(STORE,JSON.stringify(lean))}catch(e){window.__SF_SHARED_STORAGE_FAILED=true}const last=(shared.sourceFiles||[]).map(x=>x.lastDate||x.date).filter(Boolean).sort().at(-1)||up.map(x=>x.d||x.date).filter(Boolean).sort().at(-1)||'';window.__SF_SHARED_LAST=last;status(short(last));return last}
(async()=>{setBrand();try{if('serviceWorker'in navigator)(await navigator.serviceWorker.getRegistrations()).forEach(r=>r.unregister());if(window.caches){for(const k of await caches.keys())if(k.startsWith('sales-forecast-static-'))await caches.delete(k)}}catch(e){}let last='';try{last=await hydrate()}catch(e){status('공용 데이터 연결 오류: '+e.message)}await load('v16-legacy.js?v=36');await load('shared-v31.js?v=36');await load('master-upload-v34.js?v=36');setBrand();const restore=()=>{if(window.__SF_SHARED_LAST)status(short(window.__SF_SHARED_LAST))};restore();setTimeout(restore,250);setTimeout(restore,900);window.__sfCoreReady=true;window.dispatchEvent(new Event('sf-core-ready'))})().catch(e=>status('대시보드 로딩 오류: '+e.message));
})();